const parameterizedRequests = $json.parameterizedRequests || [];
const target = $json.target;
const origin = $json.origin;

const safeUrlRe = /^https?:\/\/[a-zA-Z0-9.\-]+(:\d+)?\/[a-zA-Z0-9\/_\-.%=&?+~]*$/;
// Well-known real-time/infra protocol paths that carry no real application
// parameters (Socket.IO's polling handshake, webpack HMR, etc.) - generic
// across many JS frameworks, not specific to any one target.
const infraPathRe = /\/(socket\.io|sockjs-node|__webpack_hmr|hot-update)\//i;
// Protocol-token param names that indicate a transport/handshake query
// string rather than application data.
const infraParamRe = /^(EIO|transport|sid|t|callback|jsonp)$/i;

function paramNamesFrom(str) {
  if (!str) return [];
  return str.split('&').map(p => p.split('=')[0]).filter(Boolean);
}
function looksLikeAppParam(names) {
  return names.length === 0 || names.some(n => !infraParamRe.test(n));
}

// GET query-string params AND POST body params are both real injection
// surfaces - Juice Shop's own well-known SQLi (the login form's `email`
// field) is a POST body, and was being silently dropped entirely by an
// earlier version of this filter that only ever considered GET requests.
const allCandidates = parameterizedRequests.filter(r => {
  if (!r || !r.url || !r.url.startsWith(origin)) return false;
  const basePath = r.url.split('?')[0];
  if (!safeUrlRe.test(basePath) || infraPathRe.test(r.url)) return false;
  if (r.method === 'GET') {
    const q = r.url.split('?')[1];
    if (!q || r.url.includes("'")) return false;
    return looksLikeAppParam(paramNamesFrom(q));
  }
  if (r.method === 'POST' && r.body && !r.body.includes("'")) {
    return looksLikeAppParam(paramNamesFrom(r.body));
  }
  return false;
});
// Dedupe by method+url+body - AJAX-spider can observe the same request more
// than once (e.g. a failed and successful login attempt to the same URL).
const seen = new Set();
const uniqueCandidates = allCandidates.filter(r => {
  const key = `${r.method} ${r.url} ${r.body || ''}`;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

// Test every real discovered candidate, not just the first - one endpoint
// coming back clean says nothing about the others (real-world targets
// commonly have several independent parameterized surfaces, GET and POST
// alike). Capped so N candidates can't run away unbounded; each gets its
// own short timeout.
const MAX_TARGETS = 10;
const candidateCount = uniqueCandidates.length;
const chosen = uniqueCandidates.slice(0, MAX_TARGETS);

const shQuote = (s) => "'" + String(s).replace(/'/g, "'\\''") + "'";

let command, targetsUsed = [], fallbackCrawl = false;
if (chosen.length) {
  targetsUsed = chosen.map(c => c.url);
  // A marker line before each pass carries method|url so the parser can
  // attribute findings back to the specific endpoint (and whether it was a
  // GET or POST target) they came from.
  const perTargetCmds = chosen.map(c => {
    const dataFlag = c.method === 'POST' ? ` --data ${shQuote(c.body)}` : '';
    return `echo '=== SQLMAP TARGET: ${c.method}|${c.url} ==='; timeout 25 sqlmap -u ${shQuote(c.url)}${dataFlag} --batch --level=1 --risk=1 --output-dir=/tmp/sqlmap --disable-coloring 2>&1 || true`;
  });
  command = perTargetCmds.join('; ');
} else {
  command = `timeout 150 sqlmap -u "${origin}/" --crawl=2 --forms --batch --level=1 --risk=1 --output-dir=/tmp/sqlmap --disable-coloring 2>&1 || true`;
  fallbackCrawl = true;
}
return [{ json: { target, origin, command, targetsUsed, fallbackCrawl, candidateCount, testedCount: chosen.length } }];

const stdout = $json.stdout || '';
const cmdCtx = $('Build SQLMap Command').item.json;

function parseParamBlocks(text) {
  const findings = [];
  const paramBlocks = text.split(/Parameter:\s+/).slice(1);
  for (const block of paramBlocks) {
    const paramName = block.split(/[\s(]/)[0];
    const typeMatch = block.match(/Type:\s*(.+)/);
    const titleMatch = block.match(/Title:\s*(.+)/);
    findings.push({ parameter: paramName, type: typeMatch ? typeMatch[1].trim() : null, title: titleMatch ? titleMatch[1].trim() : null });
  }
  return findings;
}

let results;
if (cmdCtx.fallbackCrawl) {
  const findings = parseParamBlocks(stdout);
  const vulnerable = /sqlmap identified the following injection point/i.test(stdout) || findings.length > 0;
  results = [{ url: 'blind homepage crawl', method: null, vulnerable, findings }];
} else {
  // Split on our own "METHOD|URL" marker line so each target's sqlmap
  // output is parsed independently and findings are attributed to the
  // right endpoint (and whether it was a GET or POST target).
  const parts = stdout.split(/=== SQLMAP TARGET: (.+?)\|(.+?) ===/).slice(1);
  results = [];
  for (let i = 0; i < parts.length; i += 3) {
    const method = parts[i];
    const url = parts[i + 1];
    const body = parts[i + 2] || '';
    const findings = parseParamBlocks(body);
    const vulnerable = /sqlmap identified the following injection point/i.test(body) || findings.length > 0;
    results.push({ url, method, vulnerable, findings });
  }
}

const vulnerable = results.some(r => r.vulnerable);
return [{ json: {
  skipped: false,
  vulnerable,
  results,
  targetsUsed: cmdCtx.targetsUsed,
  fallbackCrawl: cmdCtx.fallbackCrawl,
  candidateCount: cmdCtx.candidateCount,
  testedCount: cmdCtx.testedCount,
} }];
